contract InvMutTest {
    C c;
    address initialOwner;
    constructor(C _c) { c = _c; initialOwner = c.owner(); }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint beforeBalance = address(this).balance;
        address ownerBefore = c.owner();

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call succeeded, then this test contract should not have gained ether from c
        // and the owner must remain unchanged. If it reverted, no further guarantees.
        assert(reverted || (address(this).balance <= beforeBalance && c.owner() == ownerBefore));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address ownerBefore;
    constructor(C _c) { c = _c; ownerBefore = c.owner(); }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: either the call reverted, or the owner() is unchanged from the recorded ownerBefore
        assert(reverted || c.owner() == ownerBefore);
    }
    receive() external payable {}
}
